{var $v_labels = ($p['labels'] ?? null)}
{var $v_fill = ($p['fill'] ?? 60)}
{var $v_total = ($p['total'] ?? null)}
{var $v_currency = ($p['currency'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'split')}
{var $v_tone = ($p['tone'] ?? 'default')}
