            {capture $c_2}
              {=og_text(og_tpl(og_get($v_labels, ['perKg']), [og_money(og_get($v_d, ['price']), og_get($v_d, ['currency']))]))}
            {/capture}
            {=og_include('compose/Text.latte', ['size' => 'xs', 'class' => 'text-muted-foreground', 'children' => (string) $c_2])|noescape}
            {=og_include('blocks/number-field.latte', ['p' => ['value' => '1', 'name' => og_tpl('{0}-kg-{1}', [$v_id, og_get($v_d, ['id'])]), 'min' => '0', 'label' => og_tpl(og_get($v_labels, ['weightOf']), [og_get($v_d, ['name'])]), 'decrease' => og_tpl(og_get($v_labels, ['decreaseOf']), [og_get($v_d, ['name'])]), 'increase' => og_tpl(og_get($v_labels, ['increaseOf']), [og_get($v_d, ['name'])])]])|noescape}
          {/capture}
          {=og_include('compose/Stack.latte', ['gap' => '2', 'class' => 'rounded bg-card inset-ring inset-ring-border p-4', 'attrs' => og_attrs(['data-testid', 'item']), 'children' => (string) $c_3])|noescape}
        {/foreach}
      {/capture}
      {=og_include('compose/Box.latte', ['class' => og_s((og_t(og_eq($v_layout, 'split')) ? 'grid grid-cols-2 gap-4 md:grid-cols-3 lg:col-span-2' : 'grid grid-cols-2 gap-4 md:grid-cols-3 lg:col-span-3 lg:grid-cols-6')), 'attrs' => og_attrs(['data-testid', 'items']), 'children' => (string) $c_4])|noescape}
      {capture $c_11}
        {capture $c_5}
          {=og_text(og_get($v_labels, ['summary']))}
        {/capture}
        {=og_include('compose/Text.latte', ['size' => 'lg', 'weight' => 'semibold', 'children' => (string) $c_5])|noescape}
        {capture $c_6}
          {=og_text(og_get($v_labels, ['boxFill']))}
        {/capture}
        {=og_include('compose/Label.latte', ['htmlFor' => og_s(og_tpl('{0}-fill', [$v_id])), 'class' => 'text-sm text-muted-foreground', 'children' => (string) $c_6])|noescape}
        {=og_include('compose/Meter.latte', ['value' => og_s($v_fill), 'min' => og_s(0), 'max' => og_s(100), 'attrs' => og_attrs(['id', og_tpl('{0}-fill', [$v_id])])])|noescape}
        {capture $c_9}
          {capture $c_7}
            {=og_text(og_get($v_labels, ['total']))}
          {/capture}
          {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_7])|noescape}
          {capture $c_8}
            {=og_text(og_money($v_total, $v_currency))}
          {/capture}
          {=og_include('compose/Inline.latte', ['class' => 'text-2xl font-bold', 'attrs' => og_attrs(['role', 'status', 'aria-live', 'polite', 'data-testid', 'total']), 'children' => (string) $c_8])|noescape}
        {/capture}
        {=og_include('compose/Group.latte', ['gap' => '2', 'align' => 'baseline', 'justify' => 'between', 'children' => (string) $c_9])|noescape}
        {capture $c_10}
          {=og_include('icons/LucideIcon.latte', ['name' => 'shopping-bag', 'size' => 16])|noescape}
          {=og_text(og_get($v_labels, ['order']))}
        {/capture}
        {=og_include('compose/Button.latte', ['variant' => 'default', 'size' => 'lg', 'type' => 'button', 'class' => 'w-full', 'children' => (string) $c_10])|noescape}
      {/capture}
      {=og_include('compose/Stack.latte', ['gap' => '4', 'class' => og_s((og_t(og_eq($v_layout, 'split')) ? 'rounded bg-card inset-ring inset-ring-border p-6 lg:sticky lg:top-8' : 'rounded bg-card inset-ring inset-ring-border p-6 lg:col-span-3')), 'attrs' => og_attrs(['data-testid', 'summary']), 'children' => (string) $c_11])|noescape}
    {/capture}
    {=og_include('compose/Box.latte', ['class' => 'grid grid-cols-1 items-start gap-8 lg:grid-cols-3', 'children' => (string) $c_12])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'landmarkLabel' => $v_landmarkLabel], 'children' => og_markup($c_13)])|noescape}
